# coding: utf-8
import json
from pathlib import Path
from lesson_authoring import entry as E
B=[['古希腊 ek / ex','向外；离开']]
C=B+[['古希腊 ek + legein → eklektikos','从中挑选 → 有选择的'],['法语 eclectique → 英语 eclectic','不拘一家，采纳多种来源']]
D=B+[['古希腊 ek + leipein → ekleipsis','离开、缺失 → 日月的食'],['拉丁 eclipsis → 法语 eclipse → 英语 eclipse','日食、月食；遮蔽']]
W=[
E('eclectic','/ɪˈklektɪk/，也读 /ekˈlektɪk/','兼收并蓄的；风格或来源多样的','像认真挑歌的人：不只听一种流派，而是从不同风格里挑出自己喜欢的。','经法语 eclectique 来自希腊 eklektikos 有选择的；ek- 向外 + legein 挑选，合起来是从一堆东西里挑出来。',C,'an eclectic taste in music 是音乐口味很杂、欣赏多种风格；an eclectic collection 可以同时收不同年代、地区或类型的作品。它强调来源多元，不等于毫无标准地乱装。','eclectic tastes；an eclectic mix；an eclectic collection；an eclectic approach。','eccentric 是行为偏离常规、古怪；eclectic 是选材或兴趣跨多种来源。一个人的歌单很 eclectic，不代表这个人很 eccentric。',('Her playlist is an eclectic mix of jazz, folk, and electronic music.','她的歌单兼收爵士、民谣和电子音乐，风格很多样。'),('The designer took an eclectic approach to furnishing the room.','设计师布置房间时，选用了多种风格的家具。'),sources=['https://en.wiktionary.org/wiki/eclectic','https://www.etymonline.com/word/eclectic']),
E('eclecticism','/ɪˈklektɪsɪzəm/','兼收并蓄；折衷主义','不把自己锁在一个流派里，而是从几套做法中各取所需，组成自己的办法。','eclectic + -ism；把有选择地采纳不同来源，变成一种做法、倾向或思想方式。',C+[['eclectic + -ism → eclecticism','兼采多种来源的做法或倾向']],'艺术评论中的 eclecticism 常说作品融合多种风格；思想史中可译折衷主义，强调不只遵循一家理论。这里的折衷不一定是各退一步取中间值，也可以是择取不同系统的部分。','musical eclecticism；stylistic eclecticism；philosophical eclecticism。','eclecticism 是跨来源选择；compromise 是为达成一致作出让步。两者有时都译折衷，实际动作不同。',('The album is known for its musical eclecticism.','这张专辑以融合多种音乐风格而出名。'),('Her eclecticism allows her to draw ideas from several schools of thought.','她兼收并蓄，能够从多个思想流派中吸取观点。'),sources=['https://en.wiktionary.org/wiki/eclecticism','https://www.etymonline.com/word/eclecticism']),
E('eclipse','/ɪˈklɪps/','日食或月食；遮蔽；使相形见绌','某个本来显眼的东西被挡住了；换到人物和成绩上，就是另一个更耀眼的表现把它盖了过去。','经法语、拉丁语接希腊 ekleipsis，来自 ek- 向外与 leipein 离开；古人从光看似缺失或消退来命名食。',D,'a solar eclipse 是日食：月球挡住我们望向太阳的部分或全部视线；a lunar eclipse 是月食：月球进入地球的影子。动词 eclipse 还可比喻超越、盖过别人的名声或成绩。','a solar eclipse；a lunar eclipse；eclipse a previous achievement；be eclipsed by。','eclipse 不表示太阳真的消失了。比喻义的 eclipse 也不一定是物理挡住：新成就太突出，旧成就便显得没那么耀眼。',('The class used a model to explain a lunar eclipse.','全班用模型解释了月食的形成。'),('Her latest achievement eclipsed all her earlier successes.','她最新的成就让此前的成功都显得逊色了。'),sources=['https://en.wiktionary.org/wiki/eclipse','https://science.nasa.gov/eclipses/geometry/']),
E('ecliptic','/ɪˈklɪptɪk/','黄道；黄道的；与食有关的','从地球看，把太阳一年间相对背景星空的位置连起来，会得到一条天空中的路线。','经拉丁语接希腊 ekleiptikos 与食有关的；名词接拉丁 ecliptica。因日月食发生在月球靠近黄道、三者适当对齐时而得名。',D+[['希腊 ekleiptikos → 拉丁 eclipticus / ecliptica','与食有关的；相关天文名称'],['英语 ecliptic','黄道；黄道的']],'the ecliptic 通常指太阳在天球上的周年视运动路线；the ecliptic plane 是地球绕太阳公转轨道所在的平面。可以把平面想成一张桌面，再把它向四周延伸到星空。','the ecliptic；the ecliptic plane；near the ecliptic。','eclipse 是一次食现象；ecliptic 是黄道或其相关形容词。月球轨道与黄道面有倾角，所以并不是每个新月都会发生日食。',('The chart marks the ecliptic across the constellations.','星图标出了穿过各星座的黄道。'),('The Moon’s orbit is tilted relative to the ecliptic plane.','月球轨道相对于黄道面是倾斜的。'),sources=['https://en.wiktionary.org/wiki/ecliptic','https://www.nasa.gov/image-article/plane-of-ecliptic/','https://science.nasa.gov/eclipses/geometry/'])
]
ROOT=dict(id='C0357',meaning='向外；离开；偏离原位置',core='EC / EK / EX = OUT',image='从圆心往外走一步：位置离开中心，选择是从一堆里挑出来，狂喜则像暂时站到了平常的自己之外。',intro='这是希腊语 ek/ex“向外、离开”的前缀来源，英语里可见 ec- 等写法。它本身给方向，后面的成分决定“从哪里出来、离开什么”。不能看到开头 ec 就机械套用，ecology 的 eco- 另接“家、居所”。',forms='eccentric 接 ek + kentron，离开中心；eclectic 接 ek + legein，从中挑选；ecstasy 接 ek + 站立相关成分，原意包含离开通常位置、出神。eclipse 则走光缺失、消退的语义路线。',branches=[['偏离中心或常规','eccentric, eccentricity'],['出神与狂喜','ecstasy, ecstatic, ecstatically'],['从多处挑选','eclectic, eclecticism'],['光被遮蔽与天文路线','eclipse, ecliptic'],['离开、外出','exodus']],contrasts='eclectic 是兼收并蓄，eccentric 是古怪或偏心，别被近似拼写带偏。eclipse 是食或盖过，ecliptic 是黄道。这里把有关词放在一起帮助理解，不把记忆比喻当作现代科学解释。',practice='Her eclectic taste impressed even the eccentric collector.\n\n她兼收并蓄的品味，连那位古怪的收藏家都很欣赏。',words=[x['word'] for x in W]+['eccentric','eccentricity','ecstasy','ecstatic','ecstatically','exodus'],exclude={})
if __name__=='__main__':
 for name,data in [('roots_ec',[ROOT]),('words_ec',W)]:Path('.cache/batch200/drafts/root/'+name+'.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
 print(len(W),sum(len(x['examples']) for x in W))
